INSERT INTO `job_logglue` VALUES (1,77,'GLUE_GROOVY','package com.xxl.job.service.handler;\n\nimport com.xxl.job.core.context.XxlJobHelper;\nimport com.xxl.job.core.handler.IJobHandler;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport com.xxl.job.executor.service.jobhandler.TestService;\npublic class DemoGlueJobHandler extends IJobHandler {\n  \n   @Autowired\n    private TestService testService; \n\n	@Override\n	public void execute() throws Exception {\n		XxlJobHelper.log(\"XXL-JOB, Hello World.\");\n      testService.test1();\n	}\n\n}\n','testGlue',NULL,NULL,0),(2,77,'GLUE_GROOVY','package com.xxl.job.service.handler;\n\nimport com.xxl.job.core.context.XxlJobHelper;\nimport com.xxl.job.core.handler.IJobHandler;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport com.xxl.job.executor.service.jobhandler.TestService;\npublic class DemoGlueJobHandler extends IJobHandler {\n  \n   @Autowired\n    private TestService testService; \n\n	@Override\n	public void execute() throws Exception {\n		XxlJobHelper.log(\"XXL-JOB, Hello World.\");\n      testService.test1();\n	  testService.test2();\n	}\n\n}\n','测试版本2','2024-11-16 21:03:42','2024-11-16 21:03:42',0),(3,77,'GLUE_GROOVY','package com.xxl.job.service.handler;\n\nimport com.xxl.job.core.context.XxlJobHelper;\nimport com.xxl.job.core.handler.IJobHandler;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport com.xxl.job.executor.service.jobhandler.TestService;\npublic class DemoGlueJobHandler extends IJobHandler {\n  \n   @Autowired\n    private TestService testService; \n\n	@Override\n	public void execute() throws Exception {\n		XxlJobHelper.log(\"XXL-JOB, Hello World.\");\n      testService.test1();\n	}\n\n}\n','3333','2024-11-16 21:08:13','2024-11-16 21:08:13',0),(4,79,'GLUE_SHELL','#!/bin/bash\necho \"xxl-job: hello shell\"\n\necho \"脚本位置：$0\"\necho \"任务参数：$1\"\necho \"分片序号 = $2\"\necho \"分片总数 = $3\"\n\necho \"Good bye!\"\nexit 0\n','第一次shell','2024-11-17 13:1